/* MAGIC field-tile layer (docs/rules/magic_skills.md §5a): temporary fire/poison/
 * sleep/energy fields placed by spells. kind: 0 fire, 1 poison, 2 sleep, 3 energy(block). */
#define MAXFIELDS 64
typedef struct { uint16_t x, y, tile, obj_n; uint8_t kind, turns; } field_t;
static field_t        g_fields[MAXFIELDS];
static int            g_nfields=0;
static uint8_t        g_asleep[256];          /* >0 = actor is asleep for N turns (sleep field) */
/* spatial bucket index over world objects (16x16-tile buckets, 64x64 grid): compose visits
 * only the buckets overlapping the view instead of scanning all ~8000 objects every frame.
 * CSR layout: g_obkt_idx[g_obkt_start[b] .. g_obkt_start[b+1]) = object indices in bucket b.
 * Rebuilt in build_blocked (the "objects changed" hook). */
#define OBKT 64
static uint16_t       g_obkt_start[OBKT*OBKT+1];
static uint16_t       g_obkt_idx[MAXWOBJ];
/* FOREGROUND-only parallel bucket index: the same CSR layout but containing ONLY objects that can draw a
 * Foreground (top-pass) tile. The per-frame pass-1 (draw_view_objects pass 1) redraws foreground OVER the
 * actors every frame; scanning all in-view objects to find the ~handful that are foreground cost ~37 ms
 * (measured: 77 objects visited, 4 actually blitted, on the cacheless 68000). Iterating this sparse subset
 * instead cuts that to the foreground objects only. Membership is computed once per object in build_blocked
 * via obj_is_fg (complete over multi-tile + ANIMDATA/objanim frames); fg_index_selftest proves == full scan. */
static uint16_t       g_fgbkt_start[OBKT*OBKT+1];
static uint16_t       g_fgbkt_idx[MAXWOBJ];
/* LIGHT/SIGHT-only parallel bucket index: objects that emit light OR block sight. compute_light and
 * compute_visibility each scan the view's objects every non-cached (scroll) frame to find the handful of
 * emitters / sight-blockers — ~9 ms per scan. Iterating this sparse subset instead cuts that to the
 * relevant objects. Built in build_blocked via obj_is_lightsight (complete over ANIMDATA/objanim frames). */
static uint16_t       g_lsbkt_start[OBKT*OBKT+1];
static uint16_t       g_lsbkt_idx[MAXWOBJ];

/* Incremental map-scroll: g_tmp_map caches the STATIC compose layer (base tiles + lower-pass
 * objects, no actors/foreground/lighting). On a 1-tile walk it is memmove-scrolled and only the
 * lead 2-cell band is recomposed; actors, foreground objects, roofs and lighting are redrawn
 * full per frame (so no actor-erase or shifted-light artifacts). See docs/design/performance.md. */
#define TMP_T (VT*16)
static uint8_t        g_tmp_map[TMP_T*TMP_T];
static int            g_tmp_valid=0, g_tmp_px=-30000, g_tmp_py=-30000;
static int            g_avatar_hide;   /* vehicles: 1 = draw no avatar sprite (the boat IS the visual) */
static uint16_t       g_avatar_ovr;    /* vehicles: nonzero = draw this tile at centre (horse-with-rider) */
static int            g_idle_allow=0;  /* set by the caller ONLY for an animation-tick recompose (view fixed,
                                        * nothing but animation changed) -> enables the idle-incremental static
                                        * path. Cleared for every action/scroll compose (which may mutate static
                                        * tiles) so those keep the full rebuild. See predim_compose_static. */
/* Incremental PREDIM: g_dimmed_map is the DIMMED static layer (g_tmp_map dimmed by the per-cell
 * light), persisted across frames and memmove-scrolled in lockstep with g_tmp_map. Only cells
 * whose light CHANGED frame-to-frame (the view-anchored avatar globe's moving arc + emitters that
 * crossed the view edge) plus the freshly-revealed lead band are re-dimmed; every other cell is
 * reused from the shifted buffer. So the free block-copy present of PREDIM is kept, but the 598 ms
 * full re-dim collapses to edge+globe work. g_dm_light caches last frame's per-cell light (0..255,
 * vis already folded in as 0) to detect the changed cells. See docs/rules/lighting.md Stage F. */
static uint8_t        g_dimmed_map[TMP_T*TMP_T];
